UPDATE page
SET hq_status = CASE id
     WHEN #{m.id} THEN #{m.hqStatus}
    END,
    hq_size = CASE id
     WHEN #{m.id} THEN #{m.hqSize}
    END,
    width = CASE id
     WHEN #{m.id} THEN #{m.width}
    END,
    height = CASE id
     WHEN #{m.id} THEN #{m.height}
    END,
    media_type = CASE id
     WHEN #{m.id} THEN #{m.mediaType}
    END,
    duration = CASE id
     WHEN #{m.id} THEN #{m.duration}
    END,
    container = CASE id
     WHEN #{m.id} THEN #{m.container}
    END,
    video_codec = CASE id
     WHEN #{m.id} THEN #{m.videoCodec}
    END,
    audio_codec = CASE id
     WHEN #{m.id} THEN #{m.audioCodec}
    END,
    lq_root = CASE id
     WHEN #{m.id} THEN #{m.lqRoot}
    END,
    lq_path = CASE id
     WHEN #{m.id} THEN #{m.lqPath}
    END,
    lq_status = CASE id
     WHEN #{m.id} THEN #{m.lqStatus}
    END,
    lq_size = CASE id
     WHEN #{m.id} THEN #{m.lqSize}
    END,
    version = version + 1
WHERE id IN
#{m.id}
